// W1 · Plan — какие страницы поиска запрашивать.
// Нода: Code, режим «Run Once for All Items».
// Вход: нода «Any row» (Data Table → Get, Limit 1, Settings → Always Output Data = on).
//       Если таблица пустая, приходит пустой item без id.
// Первый запуск (таблица пустая) = бэкфилл: страницы 0 и 1, всё пишется со статусом seen.
// Обычный запуск: только страница 0 — 100 последних вакансий с запасом покрывают ночной интервал в 2 часа.

const firstRun = !$input.first().json.id;
const pages = firstRun ? [0, 1] : [0];

return pages.map((page) => ({ json: { page, firstRun } }));

// W1 · Parse search — разбор страниц поиска hh.ru в записи таблицы vacancies.
// Нода: Code, режим «Run Once for All Items».
// Вход: ответы HTTP Request «Search hh», по одному на страницу (Response Format = Text,
//       Include Response Headers and Status = on).
// Выход: ОДИН item —
//   { ok: true,  firstRun, vacancies: [...] }  → IF «OK?» → Split Out
//   { ok: false, reason, html }                → IF «OK?» → сохранить HTML → Stop and Error

const firstRun = Boolean($('Plan').first().json.firstRun);

// HTML-сущности раскодируем за один проход: иначе &amp;quot; станет кавычкой и сломает JSON
const NAMED = { quot: '"', amp: '&', lt: '<', gt: '>', apos: "'", nbsp: '\u00a0' };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code <= 0x10ffff ? String.fromCodePoint(code) : m;
    }
    return NAMED[e.toLowerCase()] ?? m;
  });
}

const stripTags = (s) => String(s ?? '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
const normTitle = (s) =>
  String(s ?? '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^a-zа-я0-9+#]+/g, ' ')
    .trim();

const fail = (reason, html) => [{ json: { ok: false, reason, html: String(html ?? '') } }];
// Текст ответа HTTP Request (Response Format = Text) n8n кладёт в поле data
const htmlOf = (res) => String(res.data ?? res.body ?? '');

// Формы оформления: tk = трудовой договор + SELF_EMPLOYED / INDIVIDUAL_ENTREPRENEUR / INDIVIDUAL_PERSON (ГПХ).
// Пустая строка = работодатель не указал
const contractOf = (v) =>
  [
    ...(v.acceptLaborContract ? ['tk'] : []),
    ...(v.civilLawContracts ?? []).flatMap((c) => c?.civilLawContractsElement ?? []).map((c) => c.toLowerCase()),
  ].join(',');

// Вакансия из выдачи → строка таблицы vacancies (имена полей = имена колонок)
function toRecord(v) {
  const pay = v.compensation ?? {};
  const companyId = v.company?.id ? String(v.company.id) : '';
  return {
    source: 'hh',
    external_id: String(v.vacancyId),
    // Одна вакансия в разных регионах = разные id. Склеиваем по компании и названию;
    // у скрытой компании id нет — такие не склеиваем
    dup_key: companyId ? `hh:${companyId}:${normTitle(v.name)}` : `hh:id:${v.vacancyId}`,
    title: String(v.name).trim(),
    company: String(v.company?.visibleName ?? v.company?.name ?? '').trim(),
    company_id: companyId,
    areas: v.area?.name ?? '',
    salary_from: pay.from ?? null,
    salary_to: pay.to ?? null,
    currency: pay.currencyCode ?? null,
    salary_gross: typeof pay.gross === 'boolean' ? pay.gross : null,
    experience: v.workExperience ?? '',
    employment_form: v.employmentForm ?? '',
    work_formats: (v.workFormats ?? []).flatMap((w) => w?.workFormatsElement ?? []).join(','),
    languages: (v.languages ?? [])
      .flatMap((l) => l?.language ?? [])
      .map((l) => `${l.isoCode}:${l.degree}`)
      .join(','),
    key_skills: stripTags(v.snippet?.skill),
    contract: contractOf(v),
    has_test: Boolean(v.userTestPresent),
    letter_required: Boolean(v['@responseLetterRequired']),
    responses: v.totalResponsesCount ?? null,
    snippet: [v.snippet?.req, v.snippet?.resp, v.snippet?.cond]
      .map(stripTags)
      .filter(Boolean)
      .join(' | ')
      .slice(0, 1500),
    url: `https://hh.ru/vacancy/${v.vacancyId}`,
    apply_url: `https://hh.ru/applicant/vacancy_response?vacancyId=${v.vacancyId}`,
    apply_type: 'hh',
    published_at: v.publicationTime?.$ ?? '',
    status: firstRun ? 'seen' : 'new',
  };
}

const byKey = new Map();
const seenIds = new Set();

for (const item of $input.all()) {
  const res = item.json;
  const html = htmlOf(res);

  if (res.statusCode !== 200) {
    const to = res.headers?.location ? ` → ${res.headers.location}` : '';
    return fail(`hh ответил HTTP ${res.statusCode}${to}`, html);
  }

  const tpl = html.match(/<template[^>]*id="HH-Lux-InitialState"[^>]*>([\s\S]*?)<\/template>/);
  if (!tpl) {
    // Слово «captcha» есть и на нормальной странице, поэтому смотрим на него только без InitialState
    const hint = /captcha|робот/i.test(html) ? 'похоже на капчу/блок' : 'сменилась вёрстка?';
    return fail(`Нет HH-Lux-InitialState — ${hint}`, html);
  }

  let state;
  try {
    state = JSON.parse(decodeEntities(tpl[1]));
  } catch (e) {
    return fail(`InitialState не разбирается: ${e.message}`, html);
  }

  const list = state?.vacancySearchResult?.vacancies;
  if (!Array.isArray(list)) return fail('Нет vacancySearchResult.vacancies — сменилась структура', html);

  for (const v of list) {
    if (!v?.vacancyId || !v?.name) return fail('У вакансии нет vacancyId/name — сменилась структура', html);
    const id = String(v.vacancyId);
    // Между запросами страниц вакансия может съехать со страницы 0 на страницу 1
    if (seenIds.has(id)) continue;
    seenIds.add(id);

    const rec = toRecord(v);
    const prev = byKey.get(rec.dup_key);
    if (!prev) byKey.set(rec.dup_key, rec);
    else if (rec.areas && !prev.areas.split(', ').includes(rec.areas)) prev.areas += `, ${rec.areas}`;
  }
}

// Пустая выдача по нашему запросу не бывает — считаем поломкой
if (byKey.size === 0) return fail('В выдаче 0 вакансий — сменилась структура или запрос', htmlOf($input.first().json));

return [{ json: { ok: true, firstRun, vacancies: [...byKey.values()] } }];

// W1 · Filter search — быстрые правила по данным выдачи, до захода на страницу вакансии.
// Нода: Code, режим «Run Once for All Items».
// Вход: новые вакансии из «Is new» и строки чёрного списка из «Blacklist».
// Выход: те же вакансии со status = new | rejected | seen и причиной в reasons.
// Правила — решения пользователя от 07.10.2026 (CLAUDE.md §7).

const firstRun = Boolean($('Plan').first().json.firstRun);
const rows = $('Is new').all().map((i) => i.json);

// Чёрный список: в колонке company — точное название компании, как на hh (без учёта регистра
// и пробелов по краям), или её id на hh (только цифры).
// Форму организации не сравниваем: на странице вакансии hh пишет «ООО ОнТаргет ЛАБС», в выдаче — «ОнТаргет ЛАБС»
const ORG_FORM = /^(ооо|оао|зао|пао|ао|нао|ип|тоо|нко|ано|гуп|муп|фгуп|гку|гбу|llc|ltd|inc)\.?\s+|\s+(ооо|оао|зао|пао|ао|нао|ип|тоо|llc|ltd|inc)\.?$/g;
const norm = (s) => String(s ?? '').trim().replace(/\s+/g, ' ').toLowerCase().replace(ORG_FORM, '');
const blacklist = new Set(
  $('Blacklist')
    .all()
    .map((i) => norm(i.json.company))
    .filter(Boolean),
);

const inBlacklist = (r) => blacklist.has(norm(r.company)) || blacklist.has(String(r.company_id));

// \b и \w в JS не работают с кириллицей — границы слова и окончания задаём явно
const ru = (word) => new RegExp(`(^|[^а-яё])${word}([^а-яё]|$)`, 'i');

const RULES = [
  ['без опыта', (r) => r.experience === 'noExperience'],
  ['junior/стажёр', (r) => /junior|\bintern|trainee/i.test(r.title) || ru('(стаж[её]р|младш[а-яё]*|джун[а-яё]*)').test(r.title)],
  ['Vue/Angular', (r) => /vue|angular/i.test(r.title)],
  [
    'Lead/архитектор',
    (r) =>
      (/\b(team ?lead|tech ?lead|lead|head|architect|cto)\b/i.test(r.title) ||
        ru('(тимлид[а-яё]*|техлид[а-яё]*|лид|архитектор[а-яё]*|руководител[а-яё]*)').test(r.title)) &&
      !/senior|middle/i.test(r.title) &&
      !ru('(старш[а-яё]*|ведущ[а-яё]*)').test(r.title),
  ],
  [
    'стоп-слово',
    (r) =>
      /php|wordpress|bitrix|\bqa\b|\b1c\b|teacher|tutor|instructor|o.?qituvchi/i.test(r.title) ||
      ru('(1с|битрикс[а-яё]*|преподавател[а-яё]*|тестировщик[а-яё]*|наставник[а-яё]*)').test(r.title),
  ],
  ['> 3000 откликов', (r) => (r.responses ?? 0) > 3000],
  ['чёрный список', inBlacklist],
];

return rows.map((r) => {
  if (firstRun) return { json: { ...r, status: 'seen', reasons: '' } };
  const failed = RULES.filter(([, test]) => test(r)).map(([name]) => name);
  return { json: { ...r, status: failed.length ? 'rejected' : 'new', reasons: failed.join(', ') } };
});

// W1 · Parse vacancy — полная страница вакансии + правила, которым нужно описание.
// Нода: Code, режим «Run Once for All Items».
// Вход: ответы HTTP Request «Vacancy page» — в том же порядке, что строки из «Is candidate»
//       (строки уже в таблице, у каждой есть id).
// Выход: строка целиком с обновлёнными status / reasons / description / key_skills / has_test / contract / error
//        → нода Update пишет её обратно по id. Дальше строки status = detailed оценивает нейросеть (W2).

const rows = $('Is candidate').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);

// Общий код разбора страницы вакансии hh: W1 «Parse vacancy» и W6 «Archive status».
// В Code-ноду попадает строкой «// @include n8n/shared/hh.js».

// HTML-сущности раскодируем за один проход: иначе &amp;quot; станет кавычкой и сломает JSON
const NAMED = { quot: '"', amp: '&', lt: '<', gt: '>', apos: "'", nbsp: '\u00a0' };
function decodeEntities(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code <= 0x10ffff ? String.fromCodePoint(code) : m;
    }
    return NAMED[e.toLowerCase()] ?? m;
  });
}

// Ответ HTTP Request «Vacancy page» → { v: vacancyFull.vacancy, test } или { error, statusCode }
function parsePage(res) {
  const html = String(res.data ?? res.body ?? '');
  if (res.statusCode !== 200) return { error: `страница: HTTP ${res.statusCode}`, statusCode: res.statusCode };
  const tpl = html.match(/<template[^>]*id="HH-Lux-InitialState"[^>]*>([\s\S]*?)<\/template>/);
  if (!tpl) return { error: 'страница: нет HH-Lux-InitialState' };
  try {
    const state = JSON.parse(decodeEntities(tpl[1]));
    const v = state?.vacancyView?.vacancyFull?.vacancy;
    if (!v?.description) return { error: 'страница: нет описания' };
    return { v, test: state?.applicantVacancyResponseStatuses?.[String(v.vacancyId)]?.test };
  } catch (e) {
    return { error: `страница: ${e.message}` };
  }
}

// Описание вакансии: HTML → текст с переносами строк
const htmlToText = (html) =>
  decodeEntities(
    String(html ?? '')
      .replace(/<\s*(br|\/p|\/li|\/h\d|\/div)[^>]*>/gi, '\n')
      .replace(/<li[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ''),
  )
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();

// «Работа только из РФ». Совпавший кусок пишем в reasons, чтобы ложные срабатывания было видно
const RF_ONLY = [
  /(только|исключительно)[^.\n]{0,40}(из|на территории|в|по)\s+(рф|росси)/i,
  /(находит[а-яё]*|проживать|проживани[а-яё]*|нахождени[а-яё]*|располож[а-яё]*)[^.\n]{0,30}(в|на территории|из)\s+(рф|росси)/i,
  /(налогов[а-яё]*\s+)?резидент[а-яё]*\s+(рф|росси)/i,
  /(based|located|reside\w*|living)\s+in\s+russia/i,
];

return rows.map((row, i) => {
  const page = parsePage(responses[i] ?? {});
  // Страница не открылась — вакансию не теряем: W2 оценит её по фрагменту из выдачи, ошибка видна в карточке
  if (page.error) return { json: { ...row, status: 'detailed', error: page.error } };

  const { v, test } = page;
  if (String(v.vacancyId) !== row.external_id) {
    return { json: { ...row, status: 'detailed', error: `страница: пришла вакансия ${v.vacancyId}` } };
  }

  const description = htmlToText(v.description);
  const skills = (v.keySkills ?? []).join(', ');
  const contract = [
    ...(v.acceptLaborContract ? ['tk'] : []),
    ...(v.civilLawContracts ?? []).flatMap((c) => c?.civilLawContractsElement ?? (typeof c === 'string' ? [c] : [])).map((c) => String(c).toLowerCase()),
  ].join(',');

  const reasons = [];
  if (v.status?.archived || v.closedForApplicants) reasons.push('в архиве');
  const rf = RF_ONLY.map((re) => description.match(re)).find(Boolean);
  if (rf) reasons.push(`только из РФ: «${rf[0].trim()}»`);
  if (!/react|next\.?js/i.test(`${row.title} ${skills} ${description}`)) reasons.push('нет React');

  return {
    json: {
      ...row,
      description: description.slice(0, 8000),
      key_skills: skills || row.key_skills,
      has_test: Boolean(test?.hasTests ?? row.has_test),
      contract,
      status: reasons.length ? 'rejected' : 'detailed',
      reasons: reasons.join(', '),
      error: '',
    },
  };
});

// W1 · Score job — задание для W2 Score: оценить вакансии сразу после сбора.
// Нода: Code, режим «Run Once for All Items». Стоит ниже ветки вакансий: n8n (execution order v1)
// выполняет её последней, когда новые вакансии уже detailed.
// Выход: один пустой item → «Score» (Execute Workflow, без ожидания). W2 сам берёт строки detailed
// из таблицы, а без этой ноды в W2 ушёл бы весь результат поиска со 100 вакансиями.

return [{ json: {} }];
